using System; using System.Reflection; using Avalonia.Input; class Program { static void Main() { var type = typeof(DragEventArgs).Assembly.GetType("Avalonia.Input.DataTransferExtensions"); foreach(var m in type.GetMethods()) { if (m.Name.StartsWith("Get") || m.Name.StartsWith("TryGet")) { Console.Write(m.ReturnType.Name + " " + m.Name + "("); var p = m.GetParameters(); for (int i = 0; i < p.Length; i++) { Console.Write((p[i].IsOut ? "out " : "") + p[i].ParameterType.Name + " " + p[i].Name); if (i < p.Length - 1) Console.Write(", "); } Console.WriteLine(")"); } } } }
